CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, email TEXT UNIQUE, password_hash TEXT, kind TEXT NOT NULL CHECK(kind IN ('demo','private')), created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE broker_accounts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'manual', currency TEXT NOT NULL DEFAULT 'USD', external_id TEXT, UNIQUE(user_id,provider,external_id));
CREATE TABLE portfolios(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL);
CREATE TABLE securities(ticker TEXT PRIMARY KEY, name TEXT NOT NULL, sector TEXT NOT NULL DEFAULT 'Unknown', industry TEXT NOT NULL DEFAULT 'Unknown', geography TEXT NOT NULL DEFAULT 'Unknown', color TEXT NOT NULL DEFAULT '#7895ec');
CREATE TABLE transactions(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES broker_accounts(id), timestamp TEXT NOT NULL, ticker TEXT REFERENCES securities(ticker), type TEXT NOT NULL CHECK(type IN ('BUY','SELL','DIVIDEND','DEPOSIT','WITHDRAWAL','FEE')), quantity_micros INTEGER NOT NULL DEFAULT 0 CHECK(quantity_micros>=0), price_micros INTEGER NOT NULL DEFAULT 0 CHECK(price_micros>=0), amount_cents INTEGER NOT NULL DEFAULT 0 CHECK(amount_cents>=0), fees_cents INTEGER NOT NULL DEFAULT 0 CHECK(fees_cents>=0), external_id TEXT, created_at TEXT NOT NULL, UNIQUE(account_id,external_id));
CREATE TABLE holdings(account_id TEXT NOT NULL REFERENCES broker_accounts(id), ticker TEXT NOT NULL REFERENCES securities(ticker), quantity_micros INTEGER NOT NULL, basis_cents INTEGER NOT NULL, realised_cents INTEGER NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(account_id,ticker));
CREATE TABLE price_history(ticker TEXT NOT NULL REFERENCES securities(ticker), timestamp TEXT NOT NULL, price REAL NOT NULL CHECK(price>=0), previous_close REAL, mode TEXT NOT NULL CHECK(mode IN ('DEMO','DELAYED','CACHED','REAL-TIME','MANUAL')), provider TEXT NOT NULL, PRIMARY KEY(ticker,timestamp,provider));
CREATE TABLE portfolio_snapshots(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), timestamp TEXT NOT NULL, value_cents INTEGER NOT NULL, cash_cents INTEGER NOT NULL, invested_cents INTEGER NOT NULL, net_flow_cents INTEGER NOT NULL, mode TEXT NOT NULL, complete INTEGER NOT NULL, UNIQUE(user_id,timestamp));
CREATE TABLE watchlists(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, UNIQUE(user_id,name));
CREATE TABLE watchlist_items(watchlist_id TEXT NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, ticker TEXT NOT NULL REFERENCES securities(ticker), PRIMARY KEY(watchlist_id,ticker));
CREATE TABLE alerts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('PRICE_ABOVE','PRICE_BELOW','WEIGHT_ABOVE','PORTFOLIO_DROP')), ticker TEXT REFERENCES securities(ticker), threshold REAL NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, state INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), alert_id TEXT REFERENCES alerts(id) ON DELETE CASCADE, message TEXT NOT NULL, created_at TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE news_items(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), headline TEXT NOT NULL, source TEXT NOT NULL, url TEXT NOT NULL, published_at TEXT NOT NULL, tickers TEXT NOT NULL, summary TEXT, UNIQUE(user_id,url));
CREATE TABLE research_reports(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), ticker TEXT, timestamp TEXT NOT NULL, provider TEXT NOT NULL, report_json TEXT NOT NULL);
CREATE TABLE calendar_events(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), ticker TEXT, kind TEXT NOT NULL, title TEXT NOT NULL, date TEXT NOT NULL, source_url TEXT, origin TEXT NOT NULL CHECK(origin IN ('MANUAL','PROVIDER')), UNIQUE(user_id,title,date));
CREATE TABLE settings(user_id TEXT PRIMARY KEY REFERENCES users(id), json TEXT NOT NULL);
CREATE TABLE broker_connections(user_id TEXT PRIMARY KEY REFERENCES users(id), provider TEXT NOT NULL, environment TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, synced_at TEXT, balances_json TEXT, positions_json TEXT);
